function mergeReviewTemplate(type,value){return{...DEFAULT_REVIEW_TEMPLATES[type],...(value&&typeof value==='object'?value:{})}}
function mergeActionTemplate(value){return{...DEFAULT_ACTION_TEMPLATE,...(value&&typeof value==='object'?value:{})}}
function currentReviewTemplate(type){return mergeReviewTemplate(type,state.stage?.reviewTemplates?.[type])}
function currentActionTemplate(){return mergeActionTemplate(state.stage?.actionTemplate)}
function templatesForRecord(record){
  if(!record||record.status==='draft')return{review:currentReviewTemplate(record?.type||'daily'),action:currentActionTemplate()};
  const snapshot=record.data?.templateSnapshot;
  return{review:mergeReviewTemplate(record.type,snapshot?.review),action:mergeActionTemplate(snapshot?.action)};
}
function currentTemplateSnapshot(type){return{version:1,review:clone(currentReviewTemplate(type)),action:clone(currentActionTemplate())}}

const state = { user:null, stage:null, theme:null, records:[], stats:{week:0,pending:0,total:0}, route:'daily', current:null, dirty:false, saving:false, navOpen:false, railOpen:false, reauthOpen:false, calendarMonth:null };
let modalReturnFocus=null;
async function request(path, options = {}) {
  const opts = { credentials:'same-origin', ...options, headers:{ ...(options.body && !(options.body instanceof Blob) && !(options.body instanceof ArrayBuffer) ? {'Content-Type':'application/json'} : {}), ...(options.headers||{}) } };
  if (opts.body && opts.headers['Content-Type']==='application/json' && typeof opts.body !== 'string') opts.body = JSON.stringify(opts.body);
  const res = await fetch(path,opts); const type=res.headers.get('content-type')||''; const data=type.includes('json')?await res.json():await res.blob();
  if(!res.ok){if(res.status===401&&state.user&&!state.reauthOpen&&!path.startsWith('/api/auth/'))sessionExpired();const e=new Error(data.message||'请求失败');e.code=data.error;e.status=res.status;throw e} return data;
}
function sessionExpired(){state.reauthOpen=true;openModal(`<div class="modal-head"><div><h2>登录已失效</h2><p>重新登录后，页面中尚未保存的内容仍会保留。</p></div></div><form id="reauth-form"><div class="field"><label>用户名</label><input name="username" value="${esc(state.user.username)}" readonly></div><div class="field"><label>密码</label><input name="password" type="password" minlength="15" required autocomplete="current-password"></div><div class="modal-actions"><button class="btn btn-primary">重新登录</button></div></form>`,'',true);$('#reauth-form').addEventListener('submit',async e=>{e.preventDefault();const res=await fetch('/api/auth/login',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});const data=await res.json();if(!res.ok){toast(data.message||'登录失败','error');return}state.reauthOpen=false;closeModal(true);toast('已重新登录，请再次保存')})}
function toast(message, kind='success') { const el=document.createElement('div');el.className=`toast ${kind}`;el.textContent=message;$('#toast-root').append(el);setTimeout(()=>el.remove(),3200); }
function contrastFor(hex){const h=String(hex).replace('#','');if(!/^[0-9a-f]{6}$/i.test(h))return'#fff';const [r,g,b]=[0,2,4].map(i=>parseInt(h.slice(i,i+2),16)/255).map(v=>v<=.03928?v/12.92:((v+.055)/1.055)**2.4);return .2126*r+.7152*g+.0722*b>.52?'#201d19':'#fff'}
function applyTheme(theme){const t=theme||state.theme||{},fallback=PALETTES['潮汐青'],r=document.documentElement;['primary','secondary','tertiary'].forEach((k,index)=>{const color=/^#[0-9a-f]{6}$/i.test(String(t[k]||''))?t[k]:fallback[index];r.style.setProperty(`--${k}`,color);r.style.setProperty(`--${k}-contrast`,contrastFor(color))});document.body.classList.toggle('reduce-motion',!!t.reduceMotion)}
const BEIJING_TIME_ZONE='Asia/Shanghai';
function beijingDateParts(value=new Date()){const parts=new Intl.DateTimeFormat('en-US',{timeZone:BEIJING_TIME_ZONE,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(value);const result=Object.fromEntries(parts.filter(x=>x.type!=='literal').map(x=>[x.type,x.value]));return{year:Number(result.year),month:Number(result.month),day:Number(result.day),iso:`${result.year}-${result.month}-${result.day}`}}
function today(){return beijingDateParts().iso}
function isoDate(value){const [year,month,day]=String(value).split('-').map(Number);return new Date(Date.UTC(year,month-1,day,12))}
function shiftIsoDate(value,days){const d=isoDate(value);d.setUTCDate(d.getUTCDate()+days);return d.toISOString().slice(0,10)}
function weekValue(value=today()){const x=isoDate(value);const day=x.getUTCDay()||7;x.setUTCDate(x.getUTCDate()+4-day);const y=new Date(Date.UTC(x.getUTCFullYear(),0,1));return `${x.getUTCFullYear()}-W${String(Math.ceil((((x-y)/86400000)+1)/7)).padStart(2,'0')}`}
function defaultPeriod(type){const current=today();if(type==='weekly')return weekValue(current);if(type==='monthly')return current.slice(0,7);if(type==='yearly')return current.slice(0,4);return current}
function shiftMonth(value,amount){const match=/^(\d{4})-(\d{2})$/.exec(String(value)),current=beijingDateParts(),base=match?new Date(Date.UTC(Number(match[1]),Number(match[2])-1,1,12)):new Date(Date.UTC(current.year,current.month-1,1,12));base.setUTCMonth(base.getUTCMonth()+Number(amount||0));return`${base.getUTCFullYear()}-${String(base.getUTCMonth()+1).padStart(2,'0')}`}
function formatDate(v){if(!v)return'';if(/^\d{4}-W\d{2}$/.test(v))return`${v.slice(0,4)} 年第 ${Number(v.slice(6))} 周`;if(/^\d{4}$/.test(v))return`${v} 年`;const match=/^(\d{4})-(\d{2})(?:-(\d{2}))?$/.exec(v);if(!match)return String(v);const d=new Date(Date.UTC(Number(match[1]),Number(match[2])-1,Number(match[3]||1),12));return new Intl.DateTimeFormat('zh-CN',{timeZone:BEIJING_TIME_ZONE,year:'numeric',month:'long',day:match[3]?'numeric':undefined,weekday:match[3]?'short':undefined}).format(d)}
function beijingTime(value){const d=new Date(value);return Number.isNaN(d.valueOf())?'':new Intl.DateTimeFormat('zh-CN',{timeZone:BEIJING_TIME_ZONE,hour:'2-digit',minute:'2-digit',hour12:false}).format(d)}
function beijingDateTime(value){const d=new Date(value);return Number.isNaN(d.valueOf())?'':new Intl.DateTimeFormat('zh-CN',{timeZone:BEIJING_TIME_ZONE,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(d)}
function periodDateInput(type,period){const t=TYPES[type].date;return `<input class="control mono" id="period-input" type="${t==='year'?'number':t}" ${t==='year'?'min="2000" max="2200"':''} value="${esc(period)}" aria-label="当前复盘周期，不可修改" disabled>`}
function reviewToolbar(type,period,locked){const periodLocked=period!==defaultPeriod(type),savedLabel=periodLocked?'非当前周期，仅可查看':state.current.updated_at?`${beijingTime(state.current.updated_at)} 草稿已存入纸笺`:'草稿尚未留存',lockedLabel=periodLocked?'非当前周期，仅可查看':'此卷已永久锁定',scopeLabel={daily:'仅限今日',weekly:'仅限本周',monthly:'仅限本月',quarterly:'仅限今日',yearly:'仅限本年',decision:'仅限今日'}[type],reviewTemplate=templatesForRecord(state.current).review;return `<section class="card review-toolbar type-${type}">
  <div class="review-toolbar-main">
    <div class="period-control"><span class="calendar-mark" aria-hidden="true">▦</span>${periodDateInput(type,period)}</div>
    <span class="current-period-note"><i aria-hidden="true">●</i>${scopeLabel}</span>
    <div class="method-pill"><i></i><span>三步正念：事实 → 归因 → 验证</span></div>
  </div>
  ${type==='decision'?`<div class="toolbar-decision-title"><label for="record-title">${esc(reviewTemplate.recordTitle)}</label><input id="record-title" maxlength="200" value="${esc(state.current.title||'')}" ${locked?'disabled':''} placeholder="用一句话说清正在做的决定"></div>`:''}
  <div class="review-toolbar-actions"><span class="save-state">${locked?lockedLabel:savedLabel}</span>${!locked?`<button class="btn toolbar-save" id="save-draft" type="button"><span aria-hidden="true">≋</span>留存草稿</button><button class="btn btn-red toolbar-lock" id="complete-record" type="button"><span aria-hidden="true">▣</span>${type==='decision'?'完成并封存依据':'完成并永久锁定'}</button>`:`<span class="status-chip done">${STATUS[state.current.status]}</span><button class="btn btn-ghost" data-nav="history" type="button">回到历史记录</button>`}</div>
</section>`}
function quoteFor(type,period){const offset=[...(state.user?.id||'')].reduce((a,c)=>a+c.charCodeAt(0),0)%14;let ordinal;if(/^\d{4}-\d{2}-\d{2}$/.test(period))ordinal=Math.floor(Date.parse(`${period}T00:00:00Z`)/86400000);else if(/^\d{4}-W\d{2}$/.test(period))ordinal=Number(period.slice(0,4))*53+Number(period.slice(6));else if(/^\d{4}-\d{2}$/.test(period))ordinal=Number(period.slice(0,4))*12+Number(period.slice(5));else ordinal=Number(period)||0;return QUOTES[type][((ordinal+offset)%14+14)%14]}
function recordFor(type,period){return state.records.find(r=>r.type===type&&r.period===period&&!((type==='decision')&&r.id!==state.current?.id))}
function newRecord(type,period){const data={answers:{},action:'',ifCondition:'',ifThen:'',verifyDate:'',journal:'',metrics:[],sleep:'',energy:'',risk:'',templateSnapshot:currentTemplateSnapshot(type)};return {id:null,type,period,title:'',data,status:'draft',version:0}}

function renderAuth(info={}){
  state.user=null;$('#app').innerHTML=`<main class="auth-shell">
    <section class="auth-art"><div class="brand-lockup"><div class="brand-row"><div class="seal">慎</div><div><div class="brand-cn">慎獨</div><div class="brand-en">SHENDU JOURNAL</div></div></div></div>
      <div class="auth-quote">“言寡尤，行寡悔，慎独存诚。”<small>把事实、调整与验证，留成一份不会被情绪改写的记录。</small></div></section>
    <section class="auth-panel"><form class="auth-card" id="auth-form"><h1>${info.firstRun?'建立第一枚印契':'回到自己的复盘室'}</h1><p>${info.firstRun?'第一个注册账户将成为唯一超级管理员。':'你的记录只对当前账户可见。'}</p>
      ${info.mode==='register'||info.firstRun?`<div class="field"><label for="displayName">称呼</label><input id="displayName" name="displayName" maxlength="32" autocomplete="name" placeholder="例如：止水"></div>`:''}
      <div class="field"><label for="username">用户名</label><input id="username" name="username" minlength="3" maxlength="32" autocomplete="username" required placeholder="汉字、字母、数字或 _ . -"></div>
      <div class="field"><label for="password">密码</label><input id="password" name="password" minlength="15" maxlength="128" type="password" autocomplete="${info.mode==='register'||info.firstRun?'new-password':'current-password'}" required><span class="help">至少 15 个字符。请使用密码管理器保存。</span><label class="help"><input id="show-password" type="checkbox"> 显示密码</label></div>
      <div class="error-text" id="auth-error"></div><button class="btn btn-primary btn-block" type="submit">${info.mode==='register'||info.firstRun?'创建账户并进入':'登录'}</button>
      ${!info.firstRun&&info.registrationOpen?`<p class="help" style="text-align:center;margin:18px 0 0">${info.mode==='register'?'已有账户？':'还没有账户？'} <button class="link-button" type="button" id="auth-switch">${info.mode==='register'?'返回登录':'自行注册'}</button></p>`:''}
    </form></section></main>`;
  $('#auth-form').addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);const registering=info.firstRun||info.mode==='register';try{const data=await request(`/api/auth/${registering?'register':'login'}`,{method:'POST',body:Object.fromEntries(fd)});await boot(data.user)}catch(err){$('#auth-error').textContent=err.message}});
  $('#show-password').addEventListener('change',e=>{$('#password').type=e.target.checked?'text':'password'});
  $('#auth-switch')?.addEventListener('click',()=>renderAuth({...info,mode:info.mode==='register'?'login':'register'}));
}

function navItems(){return Object.entries(TYPES).filter(([k])=>k!=='quarterly'||state.stage.showQuarter).map(([k,v])=>`<button class="nav-item ${state.route===k?'active':''}" data-nav="${k}">${navIcon(k)}<span class="nav-label">${v.label}</span><span class="nav-meta">${v.position}</span></button>`).join('')}
function sidebar(){return `<aside class="sidebar ${state.navOpen?'open':''}" id="sidebar">
  <div class="side-brand"><div class="brand-row"><div class="seal">慎</div><div><div class="brand-cn">慎獨</div><div class="brand-en">SHENDU JOURNAL</div></div></div><p class="side-quote">“言寡尤，行寡悔，慎独存诚”</p></div>
  <div class="nav-group"><div class="nav-caption">记录与复盘</div>${navItems()}</div>
  <div class="nav-group"><div class="nav-caption">我的空间</div>
    <button class="nav-item ${state.route==='history'?'active':''}" data-nav="history">${navIcon('history')}<span>历史复盘</span></button>
    <button class="nav-item ${state.route==='actions'?'active':''}" data-nav="actions">${navIcon('actions')}<span>${esc(currentActionTemplate().pageTitle)}</span><span class="nav-badge">${state.stats.pending}</span></button>
    <button class="nav-item ${state.route==='backup'?'active':''}" data-nav="backup">${navIcon('backup')}<span>数据备份</span><span class="nav-meta">.shendu</span></button>
    ${['admin','superadmin'].includes(state.user.role)?`<button class="nav-item ${state.route==='users'?'active':''}" data-nav="users">${navIcon('users')}<span>账户管理</span></button>`:''}
  </div><div class="side-spacer"></div>
  <div class="side-tools"><button class="nav-item" data-modal="theme">${navIcon('theme')}<span>主题颜色</span><span class="nav-meta">● ● ●</span></button><button class="nav-item" data-modal="stage">${navIcon('stage')}<span>阶段设置</span></button><button class="nav-item" data-nav="guide">${navIcon('guide')}<span>使用指南</span></button></div>
  <div class="side-user"><div class="user-row"><div class="avatar"><span>${esc((state.user.displayName||state.user.username)[0])}</span></div><div class="user-copy"><strong>${esc(state.user.displayName||state.user.username)}</strong><small>${state.user.role==='superadmin'?'超级管理员':state.user.role==='admin'?'管理员':'成员'}</small></div><button class="icon-btn" data-modal="account" title="账户设置" aria-label="打开账户设置"><span class="chevron-icon down" aria-hidden="true"></span></button></div></div>
</aside><div class="drawer-backdrop ${state.navOpen?'open':''}" id="drawer-backdrop"></div>`}

function topbar(){const isType=TYPES[state.route],routeLabels={history:'历史复盘',actions:currentActionTemplate().pageTitle,backup:'数据备份',users:'账户管理',guide:'使用指南'};return `<header class="topbar"><div class="crumb"><button class="mobile-menu" id="menu-toggle" type="button" data-route-icon="${state.route}" aria-label="打开目录" aria-controls="sidebar" aria-expanded="false">${navIcon(state.route)}</button><strong>${esc(isType?isType.label:(routeLabels[state.route]||'慎独'))}</strong><span>/</span><span>${formatDate(today())} · ${esc(state.stage.name)}阶段</span></div><div style="display:flex;gap:8px"><button class="btn btn-ghost mobile-rail-toggle" id="rail-toggle" aria-controls="right-rail" aria-expanded="false">阶段与日历</button><div class="privacy-pill"><i></i><span>私人复盘空间</span></div></div></header>`}
function shell(content){$('#app').innerHTML=`<div class="app-shell">${sidebar()}${topbar()}<div class="workspace"><main class="main">${content}</main>${rightRail()}</div></div>`;bindCommon()}

const SPACE_PAGE_META = {
  history:{mark:'册',note:'循迹 · 归档有序'},
  actions:{mark:'验',note:'闭环 · 让行动有回音'},
  backup:{mark:'匣',note:'守存 · 密文归档'},
  users:{mark:'印',note:'共管 · 权限有界'}
};
function spacePageHead(route,{title,description,action=''}){const meta=SPACE_PAGE_META[route];return `<header class="space-page-head space-head-${route}"><span class="space-head-watermark" aria-hidden="true">${meta.mark}</span><div class="space-head-mark" aria-hidden="true"><strong>${meta.mark}</strong></div><div class="space-head-copy"><h1>${esc(title)}</h1><p>${esc(description)}</p></div><div class="space-head-side"><small class="space-head-note">${meta.note}</small>${action?`<div class="space-head-action">${action}</div>`:''}</div></header>`}

function stageProgress(){const start=isoDate(state.stage.startDate),current=isoDate(today()),day=Math.max(1,Math.floor((current-start)/86400000)+1),days=Number(state.stage.days||90);return{day:Math.min(day,days),days,pct:Math.min(100,Math.max(0,day/days*100))}}
function calendarHtml(){const selected=/^\d{4}-\d{2}$/.test(state.calendarMonth)?state.calendarMonth:today().slice(0,7),[year,month]=selected.split('-').map(Number),first=new Date(Date.UTC(year,month-1,1,12)),last=new Date(Date.UTC(year,month,0,12)),lead=(first.getUTCDay()+6)%7;let days='';for(let i=0;i<lead;i++)days+='<span aria-hidden="true"></span>';for(let d=1;d<=last.getUTCDate();d++){const p=`${year}-${String(month).padStart(2,'0')}-${String(d).padStart(2,'0')}`,r=state.records.find(x=>x.type==='daily'&&x.period===p),cls=[p===today()?'today':'',r?.status==='draft'?'draft':r?'completed':''].filter(Boolean).join(' '),action=r?`data-calendar-record="${esc(r.id)}"`:p===today()?`data-calendar="${p}"`:'disabled aria-disabled="true"';days+=`<button class="cal-day ${cls}" ${action} aria-label="${formatDate(p)}${r?`，${STATUS[r.status]}`:p===today()?'，填写今日复盘':'，无记录'}">${d}</button>`}return `<div class="calendar-head"><button class="icon-btn" type="button" data-calendar-shift="-1" aria-label="上个月"><span class="chevron-icon left" aria-hidden="true"></span></button><strong>${year} 年 ${month} 月</strong><button class="icon-btn" type="button" data-calendar-shift="1" aria-label="下个月"><span class="chevron-icon right" aria-hidden="true"></span></button></div><div class="cal-grid">${['一','二','三','四','五','六','日'].map(x=>`<span class="dow">${x}</span>`).join('')}${days}</div>`}
function rightRail(){const p=stageProgress(),pending=state.records.filter(r=>r.status==='completed').sort((a,b)=>String(a.data.verifyDate).localeCompare(String(b.data.verifyDate))).slice(0,2);return `<aside class="right-rail ${state.railOpen?'open':''}" id="right-rail">
  <section class="card rail-card"><div class="stage-title"><span class="help">当前阶段</span><span class="badge">${p.day} / ${p.days} 天</span></div><b>${esc(state.stage.name)}</b><p>${esc(state.stage.focus)}</p><div class="progress"><i style="width:${p.pct}%"></i></div><button class="rail-link" data-modal="stage">编辑阶段设置</button></section>
  <section class="card rail-card" id="rail-calendar">${calendarHtml()}</section>
  <section class="card rail-card"><div class="stage-title"><h3>最近待验证</h3><span class="badge">${state.stats.pending} 项</span></div>${pending.length?pending.map(r=>`<button class="action-mini" data-open-action="${esc(r.id)}"><small><span>${esc(r.data.verifyDate||'未定日期')}</span><span>${esc(TYPES[r.type].label)}</span></small><p>${esc(r.data.action||'未填写行动')}</p></button>`).join(''):`<p>目前没有等待验证的行动。</p>`}</section>
</aside>`}

function weekRecordDays(){const current=today(),offset=(isoDate(current).getUTCDay()+6)%7,start=shiftIsoDate(current,-offset);return Array.from({length:7},(_,i)=>shiftIsoDate(start,i))}
function statsHtml(){const days=weekRecordDays(),filled=days.map(x=>state.records.some(r=>r.type==='daily'&&r.period===x&&r.status!=='draft')),pct=Math.round((filled.filter(Boolean).length/7)*100),pending=state.records.filter(r=>r.status==='completed').sort((a,b)=>String(a.data.verifyDate||'').localeCompare(String(b.data.verifyDate||''))),next=pending[0],due=pending.filter(r=>r.data.verifyDate&&r.data.verifyDate<=today()).length,actionTemplate=currentActionTemplate();return `<section class="stats-grid" aria-label="复盘概览">
  <button class="stat stat-week ${state.route==='daily'?'selected':''}" data-nav="daily" aria-pressed="${state.route==='daily'}"><span class="stat-top"><span><i></i>本周每日复盘</span><b class="stat-icon" aria-hidden="true">日</b></span><span class="stat-main"><strong>${state.stats.week}</strong><em>/ 7 天</em></span><span class="stat-progress"><i style="width:${pct}%"></i></span><span class="stat-scale"><span>${filled.map((x,i)=>`<i class="${x?'filled':''}" title="${days[i]}"></i>`).join('')}</span><b>${pct}% ${pct>=70?'稳健':'蓄力'}</b></span><span class="stat-foot"><small>今日继续记录</small><b>刻度志 ↗</b></span></button>
  <button class="stat stat-action ${state.route==='actions'?'selected':''}" data-nav="actions" aria-pressed="${state.route==='actions'}"><span class="stat-top"><span><i></i>${esc(actionTemplate.pendingTitle)}</span><b class="stat-icon" aria-hidden="true">验</b></span><span class="stat-main"><strong>${state.stats.pending}</strong><em>${esc(actionTemplate.countUnit)}闭环待检</em></span><span class="stat-quote">“${esc(next?.data?.action||'让每一次调整都有回音')}”</span><span class="stat-alarm">${due?`${due} ${esc(actionTemplate.countUnit)}已到验证日期`:(next?.data?.verifyDate?`${esc(next.data.verifyDate)} 回看`:'暂无逾期行动')}</span><span class="stat-foot"><small>无拖延闭环机制</small><b>检核令 ↗</b></span></button>
  <button class="stat stat-history ${state.route==='history'?'selected':''}" data-nav="history" aria-pressed="${state.route==='history'}"><span class="stat-top"><span><i></i>累计完成复盘</span><b class="stat-icon" aria-hidden="true">卷</b></span><span class="stat-main"><strong>${state.stats.total}</strong><em>篇已锁定</em></span><span class="stat-quote">以时间、版本与锁定状态保存每一份自省证据</span><span class="stat-foot"><small>不可篡改归档</small><b>查阅典藏 ↗</b></span></button>
</section>`}
function introHtml(type,period){return `<section class="card card-pad intro-card"><div class="intro-seal">引</div><div><small>${TYPES[type].label} · ${TYPES[type].position}</small><p>“${esc(quoteFor(type,period))}”</p></div></section>`}
function itemInputs(key,label,required,values=[''],locked=false){const list=(Array.isArray(values)&&values.length?values:['']).slice(0,5),head=label?`<div class="question-label"><span>${esc(label)}</span></div>`:'';return `<div class="question ${label?'':'question-embedded'}" data-question="${key}">${head}<div class="item-list">${list.map((v,i)=>`<div class="item-row"><textarea class="control" aria-label="${esc(label||key)}${i?`（补充 ${i+1}）`:''}" data-answer="${key}" data-index="${i}" maxlength="6000" ${locked?'disabled':''} placeholder="先写事实，再写判断。">${esc(v)}</textarea>${i?`<button class="remove-btn" aria-label="删除这一项" type="button" data-remove-item="${key}" data-index="${i}" ${locked?'disabled':''}>×</button>`:''}</div>`).join('')}</div>${list.length<5&&!locked?`<button class="add-item" type="button" data-add-item="${key}">＋ 再补充一项</button>`:''}</div>`}
function actionFields(data,locked,template){return `<div class="question"><div class="question-label">${esc(template.actionTitle)}</div><textarea class="control" aria-label="${esc(template.actionTitle)}" data-simple="action" maxlength="6000" ${locked?'disabled':''}>${esc(data.action||'')}</textarea></div><div class="question"><div class="question-label">${esc(template.obstacleTitle)}</div><textarea class="control" aria-label="${esc(template.obstacleTitle)}" data-simple="ifThen" maxlength="6000" ${locked?'disabled':''}>${esc(data.ifThen||'')}</textarea></div><div class="field"><label>${esc(template.verifyDateTitle)}</label><input type="date" min="${today()}" aria-label="${esc(template.verifyDateTitle)}" data-simple="verifyDate" value="${esc(data.verifyDate||'')}" ${locked?'disabled':''}></div>`}

function folioHead(number,word,title,subtitle,badge,tone,extra=''){return `<div class="folio-head ${tone}"><span class="folio-word" aria-hidden="true">${word}</span><div class="folio-title"><span class="folio-number">${number}</span><div><h2>${title}</h2><p><i></i>${subtitle}</p></div></div><div class="folio-badge"><i></i>${badge}</div>${extra}</div>`}
function gaugeCard(kind,label,en,value,target,max,unit,low,middle,high,locked){const hasValue=value!==''&&value!==null&&value!==undefined,n=Math.min(max,Math.max(0,Number(value)||0)),pct=n/max*100,targetPct=Math.min(100,Math.max(0,Number(target)||0)/max*100),good=hasValue&&Number(value)>=Number(target),inputMax=kind==='sleep'?24:max;return `<div class="gauge-card ${kind}" data-gauge-kind="${kind}" data-gauge-target="${target}" data-gauge-max="${max}" data-gauge-unit="${unit}"><div class="gauge-title"><span class="gauge-icon">${kind==='sleep'?'月':'气'}</span><span><b>${label}</b><small>${en}</small></span><em>基线 ${target}${unit}</em></div><div class="gauge-reading"><label><input type="number" data-simple="${kind}" data-gauge-input min="0" max="${inputMax}" step="${kind==='sleep'?'.5':'5'}" value="${esc(value??'')}" ${locked?'disabled':''} aria-label="${label}" placeholder="—"></label><small data-gauge-reading>${unit}${hasValue?` · ${good?'达标':'待恢复'}`:''}</small><b data-gauge-status class="${good?'good':''}">${!hasValue?'等待记录':kind==='sleep'?`${Number(value)-Number(target)>=0?'+':''}${(Number(value)-Number(target)).toFixed(1)}h ${good?'充沛达标':'尚需恢复'}`:good?'身心气韵充盈':'低于个人警戒线'}</b></div><div class="gauge"><span data-gauge-fill style="width:${pct}%"></span><i style="left:${targetPct}%" title="个人基线"></i><b data-gauge-knob style="left:${pct}%"></b></div><div class="gauge-scale"><span>${low}</span><span>${middle}</span><span>${high}</span></div></div>`}
function updateGauge(input){const card=input.closest('[data-gauge-kind]');if(!card)return;const raw=input.value.trim(),hasValue=raw!==''&&Number.isFinite(Number(raw)),max=Number(card.dataset.gaugeMax),target=Number(card.dataset.gaugeTarget),kind=card.dataset.gaugeKind,n=hasValue?Math.min(max,Math.max(0,Number(raw))):0,pct=n/max*100,good=hasValue&&Number(raw)>=target;card.querySelector('[data-gauge-fill]').style.width=`${pct}%`;card.querySelector('[data-gauge-knob]').style.left=`${pct}%`;const reading=card.querySelector('[data-gauge-reading]'),status=card.querySelector('[data-gauge-status]');reading.textContent=hasValue?`${card.dataset.gaugeUnit} · ${good?'达标':'待恢复'}`:card.dataset.gaugeUnit;status.classList.toggle('good',good);if(!hasValue)status.textContent='等待记录';else if(kind==='sleep'){const delta=Number(raw)-target;status.textContent=`${delta>=0?'+':''}${delta.toFixed(1)}h ${good?'充沛达标':'尚需恢复'}`}else status.textContent=good?'身心气韵充盈':'低于个人警戒线'}
function dailyEvidence(data,locked){const metrics=(data.metrics?.length?data.metrics:state.stage.metrics.map(m=>({name:m.name,target:m.target,action:'',status:''})));return `<section class="card section-card folio-card daily-evidence-card">${folioHead('01','One','今日证据 <span>·</span> 客观测定','以真实数值对抗主观偏向，立身心稳固之底盘','身心衡器','tone-one')}
  <div class="gauge-grid">${gaugeCard('sleep','昨夜睡眠测度','SLEEP CHRONO',data.sleep,state.stage.sleepTarget,10,'h','4.0h 亏空区','7.0h 基准线','10.0h 充沛',locked)}${gaugeCard('energy','主观精力值刻度','ENERGY INDEX',data.energy,state.stage.energyTarget,100,' / 100','0 枯竭','70 警戒线','100 圆满',locked)}</div>
  <div class="metric-heading"><span><i></i>阶段三项行动基石 · 严考</span><button type="button" id="example-toggle" ${locked?'disabled':''}>书写规范说明？</button></div>
  <div class="metric-example hidden" id="example-panel"><b>【文房自律实录准则】</b><ul><li>健身与身体执行：训练日完成预定组数；休息日严格执行恢复安排也算达标。</li><li>收入能力行动：必须包含可交付的实际成果，避免“研究了一下午”这类模糊描述。</li><li>财务秩序：当日收支睡前录入，不新增无计划透支消费。</li></ul></div>
  <div class="metric-ledger">${metrics.map((m,i)=>`<div class="metric-row metric-${i}"><i></i><div class="metric-copy"><b>${esc(m.name)}</b><small>${esc(m.target)}</small><textarea data-metric-action="${i}" maxlength="6000" placeholder="今天的具体行动" ${locked?'disabled':''}>${esc(m.action||'')}</textarea></div><div class="metric-status-control"><select data-metric-status="${i}" aria-label="${esc(m.name)}完成状态" ${locked?'disabled':''}><option value="">未记录</option>${['已达标','部分达标','未达标','计划休息'].map(x=>`<option ${m.status===x?'selected':''}>${x}</option>`).join('')}</select><span class="metric-status-chevron" aria-hidden="true"></span></div></div>`).join('')}</div>
  <div class="risk-note"><span>!</span><div><b>风险信号与偏离对策 · 诚实检视</b><input data-simple="risk" maxlength="6000" value="${esc(data.risk||'')}" ${locked?'disabled':''} placeholder="记录具体偏离或风险信号，以及次日应对动作"></div></div></section>`}

function dailyReflection(data,locked,template){return `<section class="card section-card folio-card">${folioHead('02','Two','看见事实 <span>·</span> 也看见原因','区分客观事实与心绪偏见，探寻深层确定性成因','格物求真','tone-two')}
  <div class="reflection-question"><div class="reflection-label"><b class="bracket-title">【${esc(template.today)}】</b><small>先写事实 · 再述心绪</small></div><p>不记流水账，只挑拨动心绪或改变行动走势的关键节点。</p>${itemInputs('today','',false,data.answers?.today,locked)}</div>
  <div class="reflection-question"><div class="reflection-label"><b class="bracket-title">【${esc(template.cause)}】</b><small>提炼正向可复用做法</small></div><p>究竟是外力偶然还是系统设计带来的必然？提炼可复用的行为定式。</p>${itemInputs('cause','',false,data.answers?.cause,locked)}</div></section>`}

function dailyActionFields(data,locked,template){const action=data.action||data.answers?.tomorrow?.[0]||'';return `<section class="card section-card folio-card">${folioHead('03','Three','给明天一个具体的开始','不留悬空的承诺，锁定明朝第一行实证动作','行动锁定','tone-three')}
  <div class="action-lock focus-lock"><div class="action-label"><b class="bracket-title">【${esc(template.actionTitle)}】</b><span>唯一焦点 · 不可分心</span></div><p>如果明天只能完成一件事，哪件事能让整天变得有价值？</p><input data-simple="action" maxlength="6000" value="${esc(action)}" ${locked?'disabled':''} placeholder="写下一个具体、可开始的动作"></div>
  <div class="action-lock"><div class="action-label"><b class="bracket-title">【${esc(template.obstacleTitle)}】</b><span>条件—行动预案</span></div><p>提前为意志力崩溃或外界干扰写好自动化应对机制。</p><div class="if-then"><input data-simple="ifCondition" maxlength="6000" value="${esc(data.ifCondition||'')}" ${locked?'disabled':''} aria-label="如果遇到的阻碍" placeholder="如果……"><i>→</i><input data-simple="ifThen" maxlength="6000" value="${esc(data.ifThen||'')}" ${locked?'disabled':''} aria-label="那么采取的行动" placeholder="那么我就……"></div></div>
  <div class="action-lock verify-lock"><div><b>◷ ${esc(template.verifyDateTitle)}</b><p>设定闭环检测锚点，实际验证时间会在提交结果时自动记录。</p></div><input type="date" min="${today()}" data-simple="verifyDate" value="${esc(data.verifyDate||'')}" ${locked?'disabled':''} aria-label="${esc(template.verifyDateTitle)}"><span>到期回看</span></div></section>`}

function dailyJournal(data,locked){return `<section class="card section-card folio-card">${folioHead('04','Four','留一页 <span>·</span> 今天的日记','自由流淌的文心独白，墨染微澜而神思澄澈','私密手札','tone-four')}<div class="journal-paper"><div class="journal-meta"><span><b>慎独斋</b> 夜读随想手札</span><small>${formatDate(state.current.period)} · 案前独坐</small></div><textarea data-simple="journal" maxlength="6000" rows="8" ${locked?'disabled':''} placeholder="选填。这里不需要结论。">${esc(data.journal||'')}</textarea><div class="journal-foot"><span>私人空间加密存储 · <strong id="journal-count">${(data.journal||'').length} 字</strong></span><b>${esc(state.user.displayName.slice(0,2))}</b></div></div></section>`}

function renderReview(type,period=state.current?.type===type?state.current.period:defaultPeriod(type),forceNew=false,draftOverride=null){
  let rec=draftOverride||(!forceNew?state.records.find(r=>r.type===type&&r.period===period):null);
  if(type==='decision'&&!state.current?.id&&forceNew)rec=null;
  state.current=rec?clone(rec):newRecord(type,period);state.dirty=false;
  const locked=state.current.status!=='draft'||period!==defaultPeriod(type),data=state.current.data||{},templates=templatesForRecord(state.current),reviewTemplate=templates.review,actionTemplate=templates.action,questions=QUESTIONS[type].map(([key,label,required])=>[key,reviewTemplate[key]||label,required]);
  if(type==='daily'&&!data.metrics?.length)data.metrics=state.stage.metrics.map(m=>({name:m.name,target:m.target,action:'',status:''}));
  const content=`<div class="stack">${introHtml(type,period)}${statsHtml()}${reviewToolbar(type,period,locked)}
    ${type==='daily'?`${dailyEvidence(data,locked)}${dailyReflection(data,locked,reviewTemplate)}${dailyActionFields(data,locked,reviewTemplate)}${dailyJournal(data,locked)}`:`<section class="card section-card folio-card">${folioHead('01','One',type==='decision'?'决定前记录':'看见事实 <span>·</span> 也看见原因','每个问题最多记录 5 项，每项最多 6000 字。',type==='decision'?'决策依据':'深度归因','tone-one')}${questions.map(q=>itemInputs(q[0],q[1],q[2],data.answers?.[q[0]],locked)).join('')}</section><section class="card section-card folio-card">${folioHead('02','Two',type==='decision'?'把决定接到行动':'把洞察变成下一步行动','让承诺有动作、有预案，也有回看的时间。','行动锁定','tone-two')}${actionFields(data,locked,reviewTemplate)}</section>`}
    ${locked&&state.current.status==='completed'?`<section class="card section-card"><h2 style="margin-top:0">${esc(actionTemplate.lockedPendingTitle)}</h2><p class="help">${esc(actionTemplate.expectedDateLabel)}：${esc(data.verifyDate||actionTemplate.expectedMissingText)}。${esc(actionTemplate.lockedPendingIntro)}</p><button class="btn btn-primary" data-open-action="${esc(state.current.id)}">${esc(actionTemplate.lockedPendingButton)}</button></section>`:''}
    ${state.current.status==='verified'?verificationRead(state.current):''}
  </div>`;
  shell(content);bindReview();
}
function verificationRead(rec){const v=rec.verification||{},t=templatesForRecord(rec).action;return `<section class="card section-card verification-result-card"><div class="section-head"><div class="section-title"><span class="art-num">验</span><div><h2>${esc(t.lockedTitle)}</h2><p>${esc(t.lockedIntro)}</p></div></div></div>${verificationTimes(rec,t)}<div class="action-part action-result-part"><div class="action-part-heading"><div><span>${esc(t.reviewEyebrow)}</span><h3>${esc(t.reviewTitle)}</h3></div><small>${esc(t.reviewNote)}</small></div><div class="action-detail-grid"><section class="action-detail result-detail"><div class="action-detail-head"><span>01</span><h3>${esc(t.resultTitle)}</h3></div><p>${esc(v.result||t.missingResultText)}</p></section><section class="action-detail adjustment-detail"><div class="action-detail-head"><span>02</span><h3>${esc(t.adjustmentTitle)}</h3></div><p>${esc(v.adjustment||t.missingResultText)}</p></section></div>${rec.type==='decision'?`<div class="decision-result-badges"><span class="badge">${esc(t.decisionOutcomeLabel)}：${esc(v.outcome||'—')}</span><span class="badge">${esc(t.decisionProcessLabel)}：${esc(v.process||'—')}</span></div>`:''}</div></section>`}

function bindReview(){
  const mark=()=>{if(state.current.status==='draft'){state.dirty=true;$('.save-state')&&($('.save-state').textContent='有未保存内容')}};
  $$('.main input,.main textarea,.main select').forEach(el=>el.addEventListener('input',()=>{mark();if(el.matches('[data-gauge-input]'))updateGauge(el);if(el.dataset.simple==='journal')$('#journal-count').textContent=`${el.value.length} 字`}));
  $('#example-toggle')?.addEventListener('click',()=>$('#example-panel').classList.toggle('hidden'));
  $$('[data-add-item]').forEach(b=>b.addEventListener('click',()=>{collectCurrent();const k=b.dataset.addItem;state.current.data.answers[k]=state.current.data.answers[k]||[''];if(state.current.data.answers[k].length<5)state.current.data.answers[k].push('');state.dirty=true;renderReviewFromCurrent()}));
  $$('[data-remove-item]').forEach(b=>b.addEventListener('click',()=>{collectCurrent();state.current.data.answers[b.dataset.removeItem].splice(Number(b.dataset.index),1);state.dirty=true;renderReviewFromCurrent()}));
  $('#save-draft')?.addEventListener('click',saveCurrent);
  $('#complete-record')?.addEventListener('click',completeCurrent);
}
function renderReviewFromCurrent(){const keep=clone(state.current);renderReview(keep.type,keep.period,false,keep);state.current=keep;state.dirty=true;const data=state.current.data;$$('[data-answer]').forEach(el=>el.value=data.answers?.[el.dataset.answer]?.[Number(el.dataset.index)]||'');$$('[data-simple]').forEach(el=>el.value=data[el.dataset.simple]||'');}
function collectCurrent(){if(!state.current)return;const d=state.current.data||(state.current.data={});d.answers=d.answers||{};$$('[data-answer]').forEach(el=>{const k=el.dataset.answer,i=Number(el.dataset.index);d.answers[k]=d.answers[k]||[];d.answers[k][i]=el.value});$$('[data-simple]').forEach(el=>d[el.dataset.simple]=el.value);$$('[data-metric-action]').forEach(el=>{const i=Number(el.dataset.metricAction);d.metrics[i].action=el.value});$$('[data-metric-status]').forEach(el=>{const i=Number(el.dataset.metricStatus);d.metrics[i].status=el.value});if($('#record-title'))state.current.title=$('#record-title').value;if(state.current.status==='draft')d.templateSnapshot=currentTemplateSnapshot(state.current.type)}
function validateCurrent(){collectCurrent();const r=state.current,d=r.data,missing=[],template=templatesForRecord(r).review;for(const [k,label,required] of QUESTIONS[r.type])if(required&&!(d.answers?.[k]||[]).some(v=>String(v).trim()))missing.push(template[k]||label);if(r.type==='decision'&&!r.title.trim())missing.push(template.recordTitle);if(!String(d.action||'').trim())missing.push(template.actionTitle);if(r.type==='daily'&&!String(d.ifCondition||'').trim())missing.push('如果遇到的阻碍');if(!String(d.ifThen||'').trim())missing.push(template.obstacleTitle);if(!d.verifyDate||d.verifyDate<today())missing.push(`${template.verifyDateTitle}（不能早于今天）`);return missing}
async function saveCurrent(silent=false){collectCurrent();state.saving=true;try{const {record}=await request('/api/records',{method:'PUT',body:state.current});state.current=record;const i=state.records.findIndex(r=>r.id===record.id);if(i>=0)state.records[i]=record;else state.records.push(record);state.dirty=false;$('.save-state')&&($('.save-state').textContent=`${beijingTime(record.updated_at)} 草稿已存入纸笺`);if(!silent)toast('草稿已保存');return record}catch(e){toast(e.message,'error');if(e.code==='version_conflict')await refreshData();throw e}finally{state.saving=false}}
async function completeCurrent(){const missing=validateCurrent();if(missing.length){toast(`请先填写：${missing.slice(0,3).join('、')}${missing.length>3?'等':''}`,'error');return}openModal(`<div class="modal-head"><div><h2>${state.current.type==='decision'?'完成并封存依据？':'完成并永久锁定？'}</h2><p>锁定后，正文、标题、日期、日记和行动都不能修改。</p></div><button class="modal-close" data-close>×</button></div><div class="lock-summary">复盘周期：${esc(state.current.period)}<br>预期验证日期：${esc(state.current.data.verifyDate)}<br>可提前或到期后提交，系统会自动记录实际验证时间。</div><div class="modal-actions"><button class="btn btn-ghost" data-close>再检查一下</button><button class="btn btn-red" id="confirm-complete">确认完成并锁定</button></div>`);$('#confirm-complete').addEventListener('click',async()=>{try{if(!state.current.id)await saveCurrent(true);else if(state.dirty)await saveCurrent(true);const {record}=await request(`/api/records/${state.current.id}/complete`,{method:'POST'});const i=state.records.findIndex(x=>x.id===record.id);state.records[i]=record;state.current=record;closeModal();await refreshStats();toast('复盘已完成并锁定');renderReview(record.type,record.period)}catch(e){toast(e.message,'error')}})}

function recordSummary(r){const vals=Object.values(r.data.answers||{}).flat().filter(Boolean);return vals[0]||r.data.action||'这份记录还没有正文摘要。'}
function isoWeekAnchor(period){const match=/^(\d{4})-W(\d{2})$/.exec(String(period));if(!match)return'';const year=Number(match[1]),week=Number(match[2]);if(week<1||week>53)return'';const jan4=new Date(Date.UTC(year,0,4,12)),weekday=jan4.getUTCDay()||7;jan4.setUTCDate(jan4.getUTCDate()+(4-weekday)+(week-1)*7);return jan4.toISOString().slice(0,10)}
function historyYear(record){const match=/^(\d{4})/.exec(String(record?.period||''));return match?match[1]:''}
function historyMonth(record){const period=String(record?.period||'');if(record?.type==='yearly')return'';if(record?.type==='weekly')return isoWeekAnchor(period).slice(0,7);const match=/^(\d{4}-\d{2})/.exec(period);return match?match[1]:''}
function renderHistory(filter={q:'',type:'all',year:'all',month:'all'},focusSearch=false){
  const active={q:String(filter.q||''),type:filter.type||'all',year:filter.year||'all',month:filter.month||'all'};
  if(active.year==='all')active.month='all';
  const years=[...new Set([today().slice(0,4),...state.records.map(historyYear).filter(Boolean)])].sort((a,b)=>b.localeCompare(a));
  const rows=state.records.filter(r=>(active.type==='all'||r.type===active.type)&&(active.year==='all'||historyYear(r)===active.year)&&(active.month==='all'||historyMonth(r)===`${active.year}-${active.month}`)&&(!active.q||`${r.title} ${JSON.stringify(r.data)}`.toLowerCase().includes(active.q.toLowerCase()))).sort((a,b)=>b.period.localeCompare(a.period));
  const hasFilter=Boolean(active.q)||active.type!=='all'||active.year!=='all'||active.month!=='all';
  shell(`${spacePageHead('history',{title:'历史复盘',description:'草稿、已完成和已验证记录都集中在这里。',action:'<button class="btn btn-primary" data-nav="daily">写今天的复盘</button>'})}<div class="filters history-filters"><input class="history-search" id="history-search" value="${esc(active.q)}" placeholder="搜索标题、正文或行动" aria-label="搜索历史复盘"><label class="history-filter-select history-type-filter"><span class="sr-only">复盘类型</span><select id="history-type"><option value="all">全部类型</option>${Object.entries(TYPES).map(([k,v])=>`<option value="${k}" ${active.type===k?'selected':''}>${v.label}</option>`).join('')}</select><span class="select-chevron" aria-hidden="true"></span></label><label class="history-filter-select history-year-filter"><span class="sr-only">年份</span><select id="history-year"><option value="all">全部年份</option>${years.map(year=>`<option value="${year}" ${active.year===year?'selected':''}>${year} 年</option>`).join('')}</select><span class="select-chevron" aria-hidden="true"></span></label><label class="history-filter-select history-month-filter"><span class="sr-only">月份</span><select id="history-month" ${active.year==='all'?'disabled':''}><option value="all">${active.year==='all'?'先选年份':'全年'}</option>${Array.from({length:12},(_,i)=>String(i+1).padStart(2,'0')).map(month=>`<option value="${month}" ${active.month===month?'selected':''}>${Number(month)} 月</option>`).join('')}</select><span class="select-chevron" aria-hidden="true"></span></label></div><div class="list" style="margin-top:18px">${rows.length?rows.map(r=>`<button class="list-item" data-open-record="${esc(r.id)}"><span class="history-type-icon type-${r.type}" aria-label="${TYPES[r.type].label}"><span>${TYPE_ICONS[r.type]}</span></span><span class="list-main"><strong>${esc(r.title||formatDate(r.period))}</strong><p>${esc(recordSummary(r))}</p></span><span class="badge ${r.status}">${STATUS[r.status]}</span></button>`).join(''):`<div class="card empty"><div class="empty-mark">册</div><h3>${hasFilter?'没有找到匹配的记录':'还没有复盘记录'}</h3><p>${hasFilter?'换一个关键词、类型或日期范围。':'先从今天发生的事实开始。'}</p><button class="btn btn-primary" data-nav="daily">开始每日复盘</button></div>`}</div>`);
  const nextFilter=()=>({q:$('#history-search').value,type:$('#history-type').value,year:$('#history-year').value,month:$('#history-month').value});
  $('#history-search').addEventListener('input',e=>renderHistory({...nextFilter(),q:e.target.value},true));
  $('#history-type').addEventListener('change',e=>renderHistory({...nextFilter(),type:e.target.value}));
  $('#history-year').addEventListener('change',e=>renderHistory({...nextFilter(),year:e.target.value,month:e.target.value==='all'?'all':$('#history-month').value}));
  $('#history-month').addEventListener('change',e=>renderHistory({...nextFilter(),month:e.target.value}));
  if(focusSearch){const input=$('#history-search');input.focus();input.setSelectionRange(input.value.length,input.value.length)}
  bindRecordOpen()
}
function bindRecordOpen(){$$('[data-open-record]').forEach(b=>b.addEventListener('click',()=>{const r=state.records.find(x=>x.id===b.dataset.openRecord);state.route=r.type;state.current=r;renderReview(r.type,r.period)}))}

function dueBadge(r,t=templatesForRecord(r).action){const d=r.data.verifyDate;if(!d)return[t.waitingStatus,''];if(d<today())return[t.overdueStatus,'overdue'];if(d===today())return[t.todayStatus,'today'];return[t.waitingStatus,'']}
function verificationActualAt(r){return r.verified_at||r.verification?.actualAt||''}
function verificationTiming(r,t=templatesForRecord(r).action){const expected=r.data?.verifyDate,actual=verificationActualAt(r);if(!expected||!actual)return null;const actualDate=beijingDateParts(new Date(actual)).iso,delta=Math.round((isoDate(actualDate)-isoDate(expected))/86400000),fill=(text,days)=>String(text).replaceAll('{days}',String(days));if(delta<0)return{label:fill(t.earlyTimingText,Math.abs(delta)),kind:'completed'};if(delta>0)return{label:fill(t.lateTimingText,delta),kind:'overdue'};return{label:t.onTimeText,kind:'today'}}
function verificationTimes(r,t=templatesForRecord(r).action){const expected=r.data?.verifyDate||'',actual=verificationActualAt(r),timing=verificationTiming(r,t);return `<div class="verification-times"><div><small>${esc(t.expectedDateLabel)}</small><strong>${expected?esc(formatDate(expected)):esc(t.expectedMissingText)}</strong></div><div><small>${esc(t.actualDateLabel)}</small><strong>${actual?esc(beijingDateTime(actual)):esc(t.actualMissingText)}</strong></div>${timing?`<span class="badge ${timing.kind}">${esc(timing.label)}</span>`:''}</div>`}
function actionPlanMarkup(r,t){const condition=String(r.data.ifCondition||'').trim(),response=String(r.data.ifThen||'').trim();if(condition)return `<div class="if-then-readonly"><div><b>${esc(t.ifLabel)}</b><span>${esc(condition)}</span></div><div><b>${esc(t.thenLabel)}</b><span>${esc(response||t.missingResponseText)}</span></div></div>`;return `<div class="if-then-readonly response-only"><div><b>${esc(t.responseLabel)}</b><span>${esc(response||t.missingPlanText)}</span></div></div>`}
function actionCard(r){const pending=r.status==='completed',t=templatesForRecord(r).action,b=pending?dueBadge(r,t):[t.verifiedStatus,'verified'],v=r.verification||{};return `<article class="card section-card action-card"><div class="section-head"><div><span class="list-type">${TYPES[r.type].label} · ${esc(r.period)}</span><h2>${esc(r.title||r.data.action||t.pageTitle)}</h2></div><span class="badge ${b[1]}">${esc(b[0])}</span></div>${verificationTimes(r,t)}<div class="action-part"><div class="action-part-heading"><div><span>${esc(t.agreementEyebrow)}</span><h3>${esc(t.agreementTitle)}</h3></div><small>${esc(t.agreementNote)}</small></div><div class="action-detail-grid"><section class="action-detail promise-detail"><div class="action-detail-head"><span>01</span><h3>${esc(t.originalActionTitle)}</h3></div><p>${esc(r.data.action||t.missingActionText)}</p></section><section class="action-detail plan-detail"><div class="action-detail-head"><span>02</span><h3>${esc(t.planTitle)}</h3></div>${actionPlanMarkup(r,t)}</section></div></div>${pending?'':`<div class="action-part action-result-part"><div class="action-part-heading"><div><span>${esc(t.reviewEyebrow)}</span><h3>${esc(t.reviewTitle)}</h3></div><small>${esc(t.reviewNote)}</small></div><div class="action-detail-grid"><section class="action-detail result-detail"><div class="action-detail-head"><span>03</span><h3>${esc(t.resultTitle)}</h3></div><p>${esc(v.result||t.missingResultText)}</p></section><section class="action-detail adjustment-detail"><div class="action-detail-head"><span>04</span><h3>${esc(t.adjustmentTitle)}</h3></div><p>${esc(v.adjustment||t.missingResultText)}</p></section></div></div>`}<div class="action-card-footer">${pending?`<button class="btn btn-primary" data-open-action="${esc(r.id)}">${esc(r.type==='decision'?t.decisionActionButton:t.submitActionButton)}</button>`:`<button class="btn btn-ghost" data-open-record="${esc(r.id)}">${esc(t.viewRecordButton)}</button>`}</div></article>`}
function renderActions(){const pending=state.records.filter(r=>r.status==='completed').sort((a,b)=>String(a.data.verifyDate).localeCompare(String(b.data.verifyDate))),verified=state.records.filter(r=>r.status==='verified').sort((a,b)=>String(verificationActualAt(b)).localeCompare(String(verificationActualAt(a)))),t=currentActionTemplate();shell(`${spacePageHead('actions',{title:t.pageTitle,description:t.pageIntro,action:`<button class="btn btn-ghost" data-nav="history">${esc(t.historyButton)}</button>`})}<section class="action-group"><div class="action-group-head"><div><h2>${esc(t.pendingTitle)}</h2><p>${esc(t.pendingIntro)}</p></div><span class="badge">${pending.length} ${esc(t.countUnit)}</span></div><div class="list">${pending.length?pending.map(actionCard).join(''):`<div class="card empty compact"><div class="empty-mark">验</div><h3>${esc(t.pendingEmptyTitle)}</h3><p>${esc(t.pendingEmptyText)}</p></div>`}</div></section><section class="action-group"><div class="action-group-head"><div><h2>${esc(t.verifiedTitle)}</h2><p>${esc(t.verifiedIntro)}</p></div><span class="badge verified">${verified.length} ${esc(t.countUnit)}</span></div><div class="list">${verified.length?verified.map(actionCard).join(''):`<div class="card empty compact"><h3>${esc(t.verifiedEmptyTitle)}</h3><p>${esc(t.verifiedEmptyText)}</p></div>`}</div></section>`);bindRecordOpen()}
function bindActionButtons(){$$('[data-open-action]').forEach(b=>b.addEventListener('click',()=>openVerification(b.dataset.openAction)))}
function decisionAdvice(outcome,process){if(outcome==='好'&&process==='好')return'保留有效方法，并提炼它适用的条件。';if(outcome==='好'&&process==='差')return'结果可能包含运气，警惕复制有问题的过程。';if(outcome==='差'&&process==='好')return'检查策略、结果滞后和环境，不必否定所有判断。';if(outcome==='差'&&process==='差')return'优先修正信息收集、风险判断与执行方法。';return''}
function openVerification(id){const r=state.records.find(x=>x.id===id);if(!r)return;const t=templatesForRecord(r).action;openModal(`<div class="modal-head"><div><h2>${esc(r.type==='decision'?t.decisionModalTitle:t.modalTitle)}</h2><p>${esc(t.modalIntro)}</p></div><button class="modal-close" data-close>×</button></div><div class="lock-summary">${esc(t.originalActionLabel)}：${esc(r.data.action||t.missingActionText)}<br>${esc(t.expectedDateLabel)}：${esc(r.data.verifyDate||t.expectedMissingText)}<br>${esc(t.actualDateLabel)}：${esc(t.actualAutoText)}</div><form id="verify-form" style="margin-top:18px"><div class="field"><label>${esc(t.resultPrompt)}</label><textarea name="result" required maxlength="6000"></textarea></div>${r.type==='decision'?`<div class="input-grid"><div class="field"><label>${esc(t.outcomePrompt)}</label><select name="outcome" required><option value="">请选择</option><option>好</option><option>差</option></select></div><div class="field"><label>${esc(t.processPrompt)}</label><select name="process" required><option value="">请选择</option><option>好</option><option>差</option></select></div></div><div class="subsection hidden" id="decision-advice"></div>`:''}<div class="field"><label>${esc(t.adjustmentPrompt)}</label><textarea name="adjustment" required maxlength="6000"></textarea></div><div class="modal-actions"><button class="btn btn-ghost" type="button" data-close>${esc(t.cancelButton)}</button><button class="btn btn-red" type="submit">${esc(t.submitButton)}</button></div></form>`);if(r.type==='decision'){$('[name=outcome]').addEventListener('change',showAdvice);$('[name=process]').addEventListener('change',showAdvice);function showAdvice(){const advice=decisionAdvice($('[name=outcome]').value,$('[name=process]').value),el=$('#decision-advice');el.textContent=advice;el.classList.toggle('hidden',!advice)}}$('#verify-form').addEventListener('submit',async e=>{e.preventDefault();try{const {record}=await request(`/api/records/${id}/verify`,{method:'POST',body:Object.fromEntries(new FormData(e.currentTarget))});const i=state.records.findIndex(x=>x.id===id);state.records[i]=record;closeModal();await refreshStats();toast('验证结果与实际时间已锁定');renderActions()}catch(err){toast(err.message,'error')}})}

function siteBackupSection(){return state.user.role==='superadmin'?`<section class="card section-card site-backup-card"><div class="section-head"><div class="section-title"><span class="art-num">站</span><div><h2>整站迁移备份</h2><p>加密打包全部账户、复盘、设置、账户密码摘要与外部备份配置。</p></div></div><span class="badge verified">仅超级管理员</span></div><div class="backup-notice">整站恢复会完整替换当前站点资料并注销所有会话。适合在新服务器搭建完成后直接迁移，无需进入服务器执行命令。</div><div class="button-row" style="justify-content:flex-start"><button class="btn btn-primary" id="site-backup-export">导出整站备份</button><label class="btn btn-ghost">恢复整站备份<input class="hidden" id="site-backup-file" type="file" accept=".shendu-site"></label></div><p class="help">整站文件使用独立密码进行 PBKDF2 + AES-256-GCM 整包加密；不会明文暴露用户名或数据统计。</p></section>`:''}

async function renderBackup(){shell(`${spacePageHead('backup',{title:'数据备份',description:'服务器内的复盘内容与导出的备份均为密文，远端只会收到加密整包。'})}<div id="backup-content"><div class="card section-card skeleton" style="height:180px"></div></div>`);try{const [status,targets]=await Promise.all([request('/api/backup/status'),request('/api/backup/targets')]);$('#backup-content').innerHTML=`<div class="stack"><section class="card section-card"><div class="section-head"><div class="section-title"><span class="art-num">密</span><div><h2>个人加密备份</h2><p>整包 PBKDF2-HMAC-SHA-256（600,000 次）与 AES-256-GCM 加密。</p></div></div><span class="badge ${status.configured?'completed':status.available?'':'overdue'}">${status.configured?'密码已设置':status.available?'尚未设置密码':'内部密钥待恢复'}</span></div>${status.error?`<div class="backup-notice">${esc(status.error)}</div>`:''}<div class="button-row" style="justify-content:flex-start"><button class="btn btn-soft" id="backup-password" ${status.available?'':'disabled'}>${status.configured?'修改备份密码':'设置备份密码'}</button><button class="btn btn-primary" id="backup-export" ${status.configured?'':'disabled'}>导出 .shendu</button><label class="btn btn-ghost">恢复备份<input class="hidden" id="backup-file" type="file" accept=".shendu"></label></div><p class="help">新版备份会在密文中写入所属用户名；跨账户恢复必须再次输入原用户名与该文件的备份密码，旧版加密包仍会尽量读取原 profile 进行归属校验。</p></section>${siteBackupSection()}
        <section class="card section-card"><div class="section-head"><div class="section-title"><span class="art-num">云</span><div><h2>S3 / WebDAV 外部备份</h2><p>最多 8 个目标，可手动、每天或每周执行。</p></div></div><button class="btn btn-primary" id="add-target" ${status.configured?'':'disabled'}>新增目标</button></div><div class="list">${targets.targets.length?targets.targets.map(t=>`<div class="backup-target"><div><strong>${esc(t.name)}</strong> <span class="badge">${t.kind.toUpperCase()}</span><p>${t.schedule==='manual'?'仅手动':t.schedule==='daily'?'每天':'每周'} · ${t.last_success_at?`上次成功 ${beijingDateTime(t.last_success_at)}`:'尚未成功备份'}${t.last_error?` · ${esc(t.last_error)}`:''}</p></div><div class="backup-actions"><button class="btn btn-ghost" data-target-edit="${esc(t.id)}">编辑</button><button class="btn btn-ghost" data-target-test="${esc(t.id)}">测试</button><button class="btn btn-soft" data-target-run="${esc(t.id)}">立即备份</button><button class="btn btn-danger" data-target-delete="${esc(t.id)}">删除</button></div></div>`).join(''):`<div class="empty"><div class="empty-mark">云</div><h3>还没有外部目标</h3><p>可以连接 WebDAV、Cloudflare R2、AWS S3、MinIO 等服务。</p></div>`}</div></section>
        <section class="card section-card"><h2 style="margin-top:0;font-size:1rem">最近运行记录</h2><div class="table-wrap"><table class="table"><thead><tr><th>时间</th><th>状态</th><th>说明</th></tr></thead><tbody>${targets.runs.length?targets.runs.map(r=>`<tr><td>${beijingDateTime(r.created_at)}</td><td><span class="badge ${r.status==='success'?'completed':'overdue'}">${r.status==='success'?'成功':'失败'}</span></td><td>${esc(r.message)}</td></tr>`).join(''):'<tr><td colspan="3">暂无运行记录</td></tr>'}</tbody></table></div></section></div>`;bindBackup(status,targets.targets)}catch(e){$('#backup-content').innerHTML=`<div class="card empty"><h3>备份信息加载失败</h3><p>${esc(e.message)}</p><button class="btn btn-primary" data-nav="backup">重试</button></div>`}}

function bindBackup(status,targets=[]){
  $('#backup-password')?.addEventListener('click',()=>{openModal(`<div class="modal-head"><div><h2>${status.configured?'修改':'设置'}备份密码</h2><p>至少 15 个字符。服务器无法替你找回这个密码。</p></div><button class="modal-close" data-close>×</button></div><form id="backup-pass-form"><div class="field"><label>备份密码</label><input name="password" type="password" minlength="15" maxlength="128" required autocomplete="new-password"></div><div class="modal-actions"><button type="button" class="btn btn-ghost" data-close>取消</button><button class="btn btn-primary">保存密码</button></div></form>`);$('#backup-pass-form').addEventListener('submit',async e=>{e.preventDefault();try{await request('/api/backup/password',{method:'POST',body:Object.fromEntries(new FormData(e.currentTarget))});closeModal();toast('备份密码已保存');renderBackup()}catch(err){toast(err.message,'error')}})});
  $('#backup-export')?.addEventListener('click',async event=>{const button=event.currentTarget;try{button.disabled=true;button.textContent='正在加密…';const blob=await request('/api/backup/export',{method:'POST',body:{}});downloadBlob(blob,`shendu-${today()}.shendu`);toast('个人加密备份已下载')}catch(error){toast(error.message,'error')}finally{button.disabled=false;button.textContent='导出 .shendu'}});
  $('#backup-file')?.addEventListener('change',async e=>{
    const file=e.target.files[0];
    e.target.value='';
    if(!file)return;
    if(file.size>36*1024*1024){toast('备份文件超过 36 MB，无法导入','error');return}
    try{
      toast('正在读取加密备份…');
      const encryptedBackup=await file.text();
      if(!encryptedBackup.trim())throw new Error('备份文件为空');
      openModal(`<div class="modal-head"><div><h2>输入这份备份的密码</h2><p>${esc(file.name)} · 如果这是修改密码前生成的旧备份，请填写生成它时使用的旧密码。</p></div><button class="modal-close" data-close>×</button></div><form id="restore-password-form"><div class="field"><label>备份密码</label><input name="password" type="password" minlength="15" maxlength="256" required autocomplete="current-password"></div><div class="modal-actions"><button type="button" class="btn btn-ghost" data-close>取消</button><button type="submit" class="btn btn-primary">校验备份</button></div></form>`);
      $('#restore-password-form').addEventListener('submit',async ev=>{
        ev.preventDefault();
        const submit=$('#restore-password-form button[type="submit"]');
        const password=String(new FormData(ev.currentTarget).get('password')||'');
        try{
          submit.disabled=true;submit.textContent='正在校验…';
          const preview=await request('/api/data/inspect',{method:'POST',body:{encryptedBackup,password}});
          const crossAccount=preview.requiresOwnerConfirmation===true;
          openModal(`<div class="modal-head"><div><h2>恢复前确认</h2><p>备份已通过密码、完整性与账户归属校验。</p></div><button class="modal-close" data-close>×</button></div><div class="lock-summary">备份所属账户：${esc(preview.ownerUsername||'无法识别')}<br>当前登录账户：${esc(state.user.username)}<br>导出时间：${esc(beijingDateTime(preview.exportedAt)||preview.exportedAt||'未记录')}<br>总条目：${preview.count}<br>复盘记录：${preview.counts.record||0}</div>${crossAccount?`<div class="backup-notice">检测到备份账户与当前账户不同。为防止误恢复，请重新输入备份所属用户名和生成这份文件时使用的备份密码。</div><div class="input-grid"><div class="field"><label for="source-backup-username">备份所属用户名</label><input id="source-backup-username" maxlength="32" required autocomplete="username" placeholder="输入 ${esc(preview.ownerUsername||'原用户名')}"></div><div class="field"><label for="source-backup-password">该文件的备份密码</label><input id="source-backup-password" type="password" minlength="15" maxlength="256" required autocomplete="current-password"></div></div>`:''}<div class="field" style="margin-top:16px"><label>恢复方式</label><select id="restore-mode"><option value="merge">安全合并：保留较新的记录</option><option value="replace">完整恢复：替换当前账户复盘</option></select></div><div class="modal-actions"><button class="btn btn-ghost" data-close>取消</button><button class="btn btn-red" id="apply-restore">开始恢复</button></div>`);
          $('#apply-restore').addEventListener('click',async()=>{
            const button=$('#apply-restore'),mode=$('#restore-mode').value;
            try{
              const sourceUsername=crossAccount?String($('#source-backup-username')?.value||'').trim():'';
              const restorePassword=crossAccount?String($('#source-backup-password')?.value||''):password;
              if(crossAccount&&(!sourceUsername||!restorePassword))throw new Error('请输入备份所属用户名和该文件的备份密码');
              button.disabled=true;button.textContent='正在恢复…';
              await request('/api/data/import',{method:'POST',body:{encryptedBackup,password:restorePassword,sourceUsername,mode,confirmation:mode==='replace'?'RESTORE':undefined}});
              closeModal();await refreshData();toast('备份已恢复');renderBackup();
            }catch(err){button.disabled=false;button.textContent='开始恢复';toast(err.message,'error')}
          });
        }catch(err){submit.disabled=false;submit.textContent='校验备份';toast(err.message,'error')}
      });
    }catch(err){toast(err.message,'error')}
  });
  $('#add-target')?.addEventListener('click',()=>openTargetModal());$$('[data-target-edit]').forEach(b=>b.addEventListener('click',()=>openTargetModal(targets.find(t=>t.id===b.dataset.targetEdit))));
  $$('[data-target-test]').forEach(b=>b.addEventListener('click',()=>targetAction(b.dataset.targetTest,'test')));$$('[data-target-run]').forEach(b=>b.addEventListener('click',()=>targetAction(b.dataset.targetRun,'run')));$$('[data-target-delete]').forEach(b=>b.addEventListener('click',async()=>{if(!confirm('确定删除这个外部备份目标？'))return;try{await request(`/api/backup/targets/${b.dataset.targetDelete}`,{method:'DELETE'});toast('目标已删除');renderBackup()}catch(e){toast(e.message,'error')}}));
  bindSiteBackup();
}
function downloadBlob(blob,filename){const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=filename;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function bindSiteBackup(){
  $('#site-backup-export')?.addEventListener('click',()=>{
    openModal(`<div class="modal-head"><div><h2>导出整站加密备份</h2><p>文件包含本站全部账户与资料，请设置独立密码并妥善保存。</p></div><button class="modal-close" data-close>×</button></div><form id="site-export-form"><div class="field"><label for="site-current-password">当前超级管理员登录密码</label><input id="site-current-password" name="currentPassword" type="password" minlength="15" maxlength="128" required autocomplete="current-password"></div><div class="input-grid"><div class="field"><label for="site-export-password">整站备份密码</label><input id="site-export-password" name="backupPassword" type="password" minlength="15" maxlength="128" required autocomplete="new-password"></div><div class="field"><label for="site-export-password-confirm">再次输入整站备份密码</label><input id="site-export-password-confirm" name="backupPasswordConfirm" type="password" minlength="15" maxlength="128" required autocomplete="new-password"></div></div><div class="modal-actions"><button type="button" class="btn btn-ghost" data-close>取消</button><button class="btn btn-primary" type="submit">生成并下载</button></div></form>`);
    $('#site-export-form').addEventListener('submit',async event=>{
      event.preventDefault();const form=event.currentTarget,button=form.querySelector('button[type="submit"]'),values=Object.fromEntries(new FormData(form));
      if(values.backupPassword!==values.backupPasswordConfirm){toast('两次输入的整站备份密码不一致','error');return}
      try{button.disabled=true;button.textContent='正在加密整站资料…';const blob=await request('/api/admin/site-backup/export',{method:'POST',body:{currentPassword:values.currentPassword,backupPassword:values.backupPassword}});downloadBlob(blob,`shendu-site-${today()}.shendu-site`);closeModal();toast('整站加密备份已下载')}
      catch(error){button.disabled=false;button.textContent='生成并下载';toast(error.message,'error')}
    });
  });
  $('#site-backup-file')?.addEventListener('change',async event=>{
    const file=event.target.files[0];event.target.value='';if(!file)return;
    if(file.size>128*1024*1024){toast('整站备份超过 128 MB，无法通过网页恢复','error');return}
    try{
      toast('正在读取整站加密备份…');const encryptedBackup=await file.text();if(!encryptedBackup.trim())throw new Error('整站备份文件为空');
      openModal(`<div class="modal-head"><div><h2>校验整站备份</h2><p>${esc(file.name)} · 输入生成这份整站备份时设置的密码。</p></div><button class="modal-close" data-close>×</button></div><form id="site-inspect-form"><div class="field"><label for="site-restore-password">整站备份密码</label><input id="site-restore-password" name="backupPassword" type="password" minlength="15" maxlength="256" required autocomplete="current-password"></div><div class="modal-actions"><button type="button" class="btn btn-ghost" data-close>取消</button><button class="btn btn-primary" type="submit">校验整站备份</button></div></form>`);
      $('#site-inspect-form').addEventListener('submit',async inspectEvent=>{
        inspectEvent.preventDefault();const inspectForm=inspectEvent.currentTarget,inspectButton=inspectForm.querySelector('button[type="submit"]'),backupPassword=String(new FormData(inspectForm).get('backupPassword')||'');
        try{
          inspectButton.disabled=true;inspectButton.textContent='正在校验…';const preview=await request('/api/admin/site-backup/inspect',{method:'POST',body:{encryptedBackup,backupPassword}});
          openModal(`<div class="modal-head"><div><h2>确认恢复整站资料</h2><p>备份已通过密码与完整性校验。恢复完成后所有账户都会退出登录。</p></div><button class="modal-close" data-close>×</button></div><div class="lock-summary">创建时间：${esc(beijingDateTime(preview.createdAt)||preview.createdAt||'未记录')}<br>账户：${preview.users} 个<br>复盘记录：${preview.records} 条<br>设置：${preview.settings} 项<br>外部备份目标：${preview.targets} 个</div><div class="backup-notice">此操作会删除当前站点的全部账户与资料，再恢复备份中的完整数据。请确认你保存了当前站点所需内容。</div><form id="site-restore-form"><div class="field"><label for="site-restore-current-password">当前超级管理员登录密码</label><input id="site-restore-current-password" name="currentPassword" type="password" minlength="15" maxlength="128" required autocomplete="current-password"></div><div class="field"><label for="site-restore-confirmation">输入“恢复全部资料”确认</label><input id="site-restore-confirmation" name="confirmationText" required autocomplete="off" placeholder="恢复全部资料"></div><div class="modal-actions"><button type="button" class="btn btn-ghost" data-close>取消</button><button class="btn btn-red" type="submit">完整恢复本站</button></div></form>`);
          $('#site-restore-form').addEventListener('submit',async restoreEvent=>{
            restoreEvent.preventDefault();const restoreForm=restoreEvent.currentTarget,restoreButton=restoreForm.querySelector('button[type="submit"]'),values=Object.fromEntries(new FormData(restoreForm));
            if(String(values.confirmationText||'').trim()!=='恢复全部资料'){toast('请输入“恢复全部资料”后再继续','error');return}
            try{restoreButton.disabled=true;restoreButton.textContent='正在恢复全部资料…';await request('/api/admin/site-backup/restore',{method:'POST',body:{encryptedBackup,backupPassword,currentPassword:values.currentPassword,confirmation:'RESTORE_SITE'}});closeModal();state.user=null;toast('整站资料已恢复，即将返回登录页');setTimeout(()=>location.assign('/'),1200)}
            catch(error){restoreButton.disabled=false;restoreButton.textContent='完整恢复本站';toast(error.message,'error')}
          });
        }catch(error){inspectButton.disabled=false;inspectButton.textContent='校验整站备份';toast(error.message,'error')}
      });
    }catch(error){toast(error.message,'error')}
  });
}
function openTargetModal(existing=null){openModal(`<div class="modal-head"><div><h2>${existing?'编辑':'新增'}外部备份目标</h2><p>${existing?'为安全起见，编辑时需要重新填写连接凭据。':'只接受 HTTPS 公网地址，系统会拒绝本机、私网和保留地址。'}</p></div><button class="modal-close" data-close>×</button></div><form id="target-form"><div class="input-grid"><div class="field"><label>名称</label><input name="name" required value="${esc(existing?.name||'')}" placeholder="例如：我的 R2"></div><div class="field"><label>类型</label><select name="kind" id="target-kind"><option value="webdav" ${existing?.kind==='webdav'?'selected':''}>WebDAV</option><option value="s3" ${existing?.kind==='s3'?'selected':''}>S3 兼容存储</option></select></div></div><div id="target-fields"></div><div class="field"><label>周期</label><select name="schedule"><option value="manual" ${existing?.schedule==='manual'?'selected':''}>仅手动</option><option value="daily" ${existing?.schedule==='daily'?'selected':''}>每天</option><option value="weekly" ${existing?.schedule==='weekly'?'selected':''}>每周</option></select></div><div class="modal-actions"><button type="button" class="btn btn-ghost" data-close>取消</button><button class="btn btn-primary">保存目标</button></div></form>`);const draw=()=>{$('#target-fields').innerHTML=$('#target-kind').value==='webdav'?`<div class="field"><label>WebDAV HTTPS 地址</label><input name="url" type="url" required placeholder="https://dav.example.com/remote.php/dav/files/user"></div><div class="input-grid"><div class="field"><label>账号</label><input name="username" required></div><div class="field"><label>密码 / 应用密码</label><input name="password" type="password" required></div></div><div class="field"><label>远端目录</label><input name="directory" value="shendu"></div>`:`<div class="field"><label>Endpoint</label><input name="endpoint" type="url" required placeholder="https://xxxx.r2.cloudflarestorage.com"></div><div class="input-grid"><div class="field"><label>Region</label><input name="region" value="auto"></div><div class="field"><label>Bucket</label><input name="bucket" required></div><div class="field"><label>Access Key</label><input name="accessKey" required></div><div class="field"><label>Secret Key</label><input name="secretKey" type="password" required></div></div><div class="field"><label>远端目录</label><input name="directory" value="shendu"></div><label class="help"><input type="checkbox" name="pathStyle"> 使用 Path-style 地址</label>`};draw();$('#target-kind').addEventListener('change',draw);$('#target-form').addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.currentTarget),kind=fd.get('kind'),config={};for(const [k,v] of fd)if(!['name','kind','schedule'].includes(k))config[k]=v==='on'?true:v;try{await request(existing?`/api/backup/targets/${existing.id}`:'/api/backup/targets',{method:existing?'PATCH':'POST',body:{name:fd.get('name'),kind,schedule:fd.get('schedule'),config}});closeModal();toast('外部目标已保存');renderBackup()}catch(err){toast(err.message,'error')}})}
async function targetAction(id,action){try{toast(action==='test'?'正在测试连接…':'正在生成并上传加密备份…');await request(`/api/backup/targets/${id}/${action}`,{method:'POST'});toast(action==='test'?'连接测试成功':'外部备份完成');renderBackup()}catch(e){toast(e.message,'error')}}

async function renderUsers(q=''){shell(`${spacePageHead('users',{title:'账户管理',description:'管理员只管理账户状态，不会看到任何人的复盘正文。',action:'<button class="btn btn-primary" id="add-user">创建成员</button>'})}<div id="users-content" class="card section-card users-card skeleton"></div>`);try{const data=await request(`/api/admin/users?q=${encodeURIComponent(q)}`);$('#users-content').className='card section-card users-card';$('#users-content').innerHTML=`<div class="section-head"><div class="filters"><input id="user-search" placeholder="搜索用户名或称呼" value="${esc(q)}" aria-label="搜索账户"></div>${state.user.role==='superadmin'?`<label class="help registration-toggle"><input type="checkbox" id="registration-open" ${data.registrationOpen?'checked':''}> 允许公开注册</label>`:''}</div><div class="table-wrap users-table-wrap"><table class="table users-table"><thead><tr><th>称呼</th><th>用户名</th><th>加入日期</th><th>角色</th><th>状态</th><th>操作</th></tr></thead><tbody>${data.users.map(u=>`<tr><td data-label="称呼">${esc(u.displayName)}</td><td data-label="用户名">${esc(u.username)}</td><td data-label="加入日期">${esc(u.createdAt.slice(0,10))}</td><td data-label="角色">${u.role==='superadmin'?'超级管理员':u.role==='admin'?'管理员':'成员'}</td><td data-label="状态"><span class="badge ${u.status==='active'?'completed':'overdue'}">${u.status==='active'?'正常':'停用'}</span></td><td data-label="操作">${u.id===state.user.id||u.role==='superadmin'||(state.user.role==='admin'&&u.role==='admin')?'—':`<div class="inline-actions"><button class="btn btn-ghost" data-user-toggle="${esc(u.id)}" data-status="${u.status==='active'?'disabled':'active'}">${u.status==='active'?'停用':'恢复'}</button><button class="btn btn-soft" data-user-reset="${esc(u.id)}">重置密码</button>${state.user.role==='superadmin'?`<button class="btn btn-ghost" data-user-role="${esc(u.id)}" data-role="${u.role==='admin'?'member':'admin'}">设为${u.role==='admin'?'成员':'管理员'}</button>`:''}<button class="btn btn-danger" data-user-delete="${esc(u.id)}">删除用户</button></div>`}</td></tr>`).join('')}</tbody></table></div>`;bindUsers(data.users)}catch(e){$('#users-content').className='card empty users-card';$('#users-content').innerHTML=`<h3>加载失败</h3><p>${esc(e.message)}</p>`}}
function bindUsers(users=[]){$('#user-search')?.addEventListener('change',e=>renderUsers(e.target.value));$('#registration-open')?.addEventListener('change',async e=>{try{await request('/api/admin/registration',{method:'PUT',body:{open:e.target.checked}});toast('公开注册设置已更新')}catch(err){toast(err.message,'error')}});$('#add-user')?.addEventListener('click',()=>openUserModal());$$('[data-user-toggle]').forEach(b=>b.addEventListener('click',()=>patchUser(b.dataset.userToggle,{status:b.dataset.status})));$$('[data-user-role]').forEach(b=>b.addEventListener('click',()=>patchUser(b.dataset.userRole,{role:b.dataset.role})));$$('[data-user-reset]').forEach(b=>b.addEventListener('click',()=>openUserModal(b.dataset.userReset)));$$('[data-user-delete]').forEach(b=>b.addEventListener('click',()=>{const target=users.find(u=>u.id===b.dataset.userDelete);if(target)openDeleteUserModal(target)}))}
function openDeleteUserModal(target){openModal(`<div class="modal-head"><div><h2>永久删除用户</h2><p>删除后，${esc(target.displayName)} 的复盘、设置、会话和备份目标都会一并清除。</p></div><button class="modal-close" data-close>×</button></div><div class="backup-notice delete-warning">这项操作无法撤销。请先确认已经保存所需备份。</div><form id="delete-user-form"><div class="field"><label for="delete-user-confirm">输入用户名 <strong>${esc(target.username)}</strong> 确认</label><input id="delete-user-confirm" name="confirmationUsername" required autocomplete="off" autocapitalize="none" spellcheck="false"></div><div class="field"><label for="delete-user-password">你的当前登录密码</label><input id="delete-user-password" name="currentPassword" type="password" minlength="15" maxlength="128" required autocomplete="current-password"></div><div class="modal-actions"><button type="button" class="btn btn-ghost" data-close>取消</button><button class="btn btn-red" type="submit">永久删除此用户</button></div></form>`);$('#delete-user-form').addEventListener('submit',async e=>{e.preventDefault();const body=Object.fromEntries(new FormData(e.currentTarget)),normalizeUsername=value=>String(value||'').trim().normalize('NFKC').toLocaleLowerCase('zh-CN');if(normalizeUsername(body.confirmationUsername)!==normalizeUsername(target.username)){toast('输入的用户名与待删除账户不一致','error');return}try{await request(`/api/admin/users/${target.id}`,{method:'DELETE',body});closeModal();toast(`用户 ${target.username} 已永久删除`);renderUsers()}catch(err){toast(err.message,'error')}})}
function openUserModal(resetId=null){openModal(`<div class="modal-head"><div><h2>${resetId?'重置成员密码':'创建新账户'}</h2><p>${resetId?'该账户现有登录会立即失效，复盘数据会保留。':'管理员创建的账户可以直接登录。'}</p></div><button class="modal-close" data-close>×</button></div><form id="user-form">${resetId?'':`<div class="input-grid"><div class="field"><label>称呼</label><input name="displayName" required maxlength="32"></div><div class="field"><label>用户名</label><input name="username" required minlength="3" maxlength="32"></div></div>${state.user.role==='superadmin'?`<div class="field"><label>角色</label><select name="role"><option value="member">成员</option><option value="admin">管理员</option></select></div>`:''}`}<div class="field"><label>${resetId?'新密码':'初始密码'}</label><input name="password" type="password" required minlength="15" maxlength="128" autocomplete="new-password"></div><div class="modal-actions"><button type="button" class="btn btn-ghost" data-close>取消</button><button class="btn btn-primary">确认</button></div></form>`);$('#user-form').addEventListener('submit',async e=>{e.preventDefault();try{const body=Object.fromEntries(new FormData(e.currentTarget));if(resetId)await request(`/api/admin/users/${resetId}`,{method:'PATCH',body:{password:body.password}});else await request('/api/admin/users',{method:'POST',body});closeModal();toast(resetId?'密码已重置':'账户已创建');renderUsers()}catch(err){toast(err.message,'error')}})}
async function patchUser(id,body){try{await request(`/api/admin/users/${id}`,{method:'PATCH',body});toast('账户已更新');renderUsers()}catch(e){toast(e.message,'error')}}

function renderGuide(){shell(`<div class="page-head"><div><h1>使用指南</h1><p>复盘不是审判自己，而是用证据改善下一次行动。</p></div></div><article class="card section-card prose"><div class="guide-flow">${['定标','事实','差距','机制','改变','验证'].map((x,i)=>`<div class="guide-step"><b>${String(i+1).padStart(2,'0')}</b><span>${x}</span></div>`).join('')}</div><h3>不同周期分别解决什么问题？</h3><p>每日看行动，不超过 8 分钟；每周找重复出现的条件；每月只选一个瓶颈和一个小实验；90 天重新校准方向；年度看人生结构；重大决策留下当时依据，避免事后诸葛亮。</p><h3>阶段指标怎么写？</h3><p>指标要能在一天结束时明确判断，而不是“变得更好”。例如把“提升收入能力”写成“专注 60 分钟，形成一个可展示的具体输出”。达标线是最低有效行动，不是理想状态。</p><h3>怎样避免越复盘越自责？</h3><ul><li>先写摄像头能拍到的事实，再写自己的解释。</li><li>一次只调整一个最可能影响结果的条件。</li><li>状态差时降低动作门槛，不把休息等同于失败。</li><li>验证的是方法，不是证明自己好或不好。</li></ul><h3>重大决定怎么回看？</h3><p>把过程质量与结果好坏分开。好结果可能来自运气，坏结果也不一定说明当时的判断错误。回到当时真正掌握的信息、可选方案和风险边界，再决定保留什么。</p></article>`)}

const ACTION_PROMPT_FIELDS = [
  ['resultPrompt','通用问题 1 · 实际结果'],
  ['outcomePrompt','重大决策追加问题 1 · 结果'],
  ['processPrompt','重大决策追加问题 2 · 决策过程'],
  ['adjustmentPrompt','通用问题 2 · 保留或调整']
];
function reviewTemplateEditor(type,template){
  const questionFields=QUESTIONS[type].map(([key],index)=>[key,`问题 ${index+1}`]);
  const fields=[...(type==='decision'?[["recordTitle","决定名称标题"]]:[]),...questionFields,['actionTitle','行动标题'],['obstacleTitle','阻碍预案标题'],['verifyDateTitle','验证日期标题']];
  return `<details class="template-panel" ${type==='daily'?'open':''}><summary><span class="template-type-icon type-${type}">${TYPE_ICONS[type]}</span><span><b>${TYPES[type].label}</b><small>${type==='daily'?'展示时自动保留【】样式':'只改问题与输入项标题'}</small></span><span class="template-chevron" aria-hidden="true"></span></summary><div class="template-panel-body"><div class="template-field-grid">${fields.map(([key,label])=>`<div class="field"><label>${label}</label><input aria-label="${esc(`${TYPES[type].label} ${label}`)}" data-review-template="${type}" data-template-key="${key}" maxlength="160" required value="${esc(template[key])}"></div>`).join('')}</div><button class="link-button template-reset" type="button" data-reset-review="${type}">恢复本类默认文案</button></div></details>`;
}
function actionTemplateEditor(template){return `<details class="template-panel action-template-panel"><summary><span class="template-type-icon action">验</span><span><b>行动验证</b><small>只修改提交验证时的四个问题</small></span><span class="template-chevron" aria-hidden="true"></span></summary><div class="template-panel-body"><div class="template-field-grid">${ACTION_PROMPT_FIELDS.map(([key,label])=>`<div class="field"><label>${label}</label><input aria-label="${esc(`行动验证 ${label}`)}" data-action-template data-template-key="${key}" maxlength="240" required value="${esc(template[key])}"></div>`).join('')}</div><button class="link-button template-reset" type="button" data-reset-action>恢复行动验证默认问题</button></div></details>`}
function resetTemplateInputs(selector,defaults){$$(selector).forEach(input=>{input.value=defaults[input.dataset.templateKey]||''})}

function openStage(){
  const s=clone(state.stage),reviewTemplates=Object.fromEntries(Object.keys(TYPES).map(type=>[type,mergeReviewTemplate(type,s.reviewTemplates?.[type])])),actionTemplate=mergeActionTemplate(s.actionTemplate);
  openModal(`<div class="modal-head"><div><h2>阶段与内容设置</h2><p>模板只影响草稿和之后新建的复盘；已经完成、验证或锁定的记录保留当时内容。</p></div><button class="modal-close" data-close>×</button></div><form id="stage-form"><section class="stage-settings-section"><div class="settings-section-title"><span>01</span><div><h3>当前阶段</h3><p>设定阶段长度、关注方向和每日行动基线。</p></div></div><div class="input-grid"><div class="field"><label>当前阶段</label><select name="name">${['稳住底盘','建设能力','产出增长','扩张整合'].map(x=>`<option ${s.name===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>阶段开始日期</label><input name="startDate" type="date" value="${esc(s.startDate)}" required></div><div class="field"><label>阶段长度（7–366 天）</label><input name="days" type="number" min="7" max="366" value="${s.days}" required></div><div class="field"><label>这一阶段最想改善什么</label><input name="focus" maxlength="300" value="${esc(s.focus)}" required></div><div class="field"><label>睡眠达标线（小时）</label><input name="sleepTarget" type="number" min="0" max="24" step=".5" value="${s.sleepTarget}" required></div><div class="field"><label>精力观察线（0–100）</label><input name="energyTarget" type="number" min="0" max="100" step="10" value="${s.energyTarget}" required></div></div><div class="subsection"><h3>三项阶段指标</h3>${s.metrics.map((m,i)=>`<div class="input-grid"><div class="field"><label>指标 ${i+1}</label><input name="metricName${i}" maxlength="80" value="${esc(m.name)}" required></div><div class="field"><label>具体达标线</label><input name="metricTarget${i}" maxlength="240" value="${esc(m.target)}" required></div></div>`).join('')}</div><label class="quarter-toggle-card"><span class="quarter-toggle-art"><strong>90</strong><small>DAYS</small></span><span class="quarter-toggle-copy"><b>90 天复盘</b><small>在左侧目录显示季度复盘入口，用更长周期校准方向。</small></span><input name="showQuarter" type="checkbox" ${s.showQuarter?'checked':''}><span class="quarter-switch" aria-hidden="true"></span></label></section><section class="stage-settings-section template-settings-section"><div class="settings-section-title"><span>02</span><div><h3>六类复盘内容</h3><p>只修改各类复盘下面的问题与输入项标题，不改变结构、状态或历史内容。</p></div></div><div class="template-list">${Object.keys(TYPES).map(type=>reviewTemplateEditor(type,reviewTemplates[type])).join('')}</div></section><section class="stage-settings-section template-settings-section"><div class="settings-section-title"><span>03</span><div><h3>行动验证内容</h3><p>和六类复盘一样，只修改提交验证时的问题标题，不改变页面、状态与按钮。</p></div></div>${actionTemplateEditor(actionTemplate)}</section><div class="modal-actions stage-save-actions"><button type="button" class="btn btn-ghost" data-close>取消</button><button class="btn btn-primary">保存全部设置</button></div></form>`,'wide');
  $$('[data-reset-review]').forEach(button=>button.addEventListener('click',()=>{const type=button.dataset.resetReview;resetTemplateInputs(`[data-review-template="${type}"]`,DEFAULT_REVIEW_TEMPLATES[type]);toast(`${TYPES[type].label}已恢复默认文案`)}));
  $('[data-reset-action]')?.addEventListener('click',()=>{resetTemplateInputs('[data-action-template]',DEFAULT_ACTION_TEMPLATE);toast('行动验证已恢复默认问题')});
  $('#stage-form').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget),reviewTemplates=Object.fromEntries(Object.keys(TYPES).map(type=>[type,Object.fromEntries($$(`[data-review-template="${type}"]`,e.currentTarget).map(input=>[input.dataset.templateKey,input.value.trim()]))])),actionPrompts=Object.fromEntries($$('[data-action-template]',e.currentTarget).map(input=>[input.dataset.templateKey,input.value.trim()])),savedActionTemplate={...actionTemplate,...actionPrompts},stage={name:f.get('name'),startDate:f.get('startDate'),days:Number(f.get('days')),focus:f.get('focus'),sleepTarget:Number(f.get('sleepTarget')),energyTarget:Number(f.get('energyTarget')),showQuarter:f.get('showQuarter')==='on',metrics:[0,1,2].map(i=>({name:f.get(`metricName${i}`),target:f.get(`metricTarget${i}`)})),reviewTemplates,actionTemplate:savedActionTemplate};try{const result=await request('/api/settings',{method:'PUT',body:{stage}});state.stage=result.stage||stage;closeModal();toast('阶段与内容设置已保存');navigate(state.route)}catch(err){toast(err.message,'error')}})
}

function openTheme(){const original=clone(state.theme);openModal(`<div class="modal-head"><div><h2>文房设色</h2><p>主色用于章节与按钮，辅助色用于艺术编号，次色用于统计与细节。</p></div><button class="modal-close" data-close>×</button></div><form id="theme-form"><div class="palette-grid">${Object.entries(PALETTES).map(([n,c])=>`<button type="button" class="palette ${state.theme.preset===n?'active':''}" data-palette="${n}"><strong>${n}</strong><span class="swatches">${c.map(x=>`<i style="background:${x}"></i>`).join('')}</span></button>`).join('')}</div><div class="settings-grid" style="margin-top:18px">${[['primary','主色'],['secondary','辅助色'],['tertiary','次色']].map(([k,l])=>`<div class="field"><label>${l}</label><div class="color-row"><input type="color" data-color="${k}" value="${esc(state.theme[k])}"><input name="${k}" value="${esc(state.theme[k])}" pattern="#[0-9A-Fa-f]{6}"></div></div>`).join('')}</div><label class="help"><input name="reduceMotion" type="checkbox" ${state.theme.reduceMotion?'checked':''}> 减少动态效果</label><div class="modal-actions"><button type="button" class="btn btn-ghost" id="theme-reset">恢复默认</button><button type="button" class="btn btn-ghost" data-close>取消</button><button class="btn btn-primary">保存主题</button></div></form>`);let draft=clone(state.theme);const sync=()=>{applyTheme(draft);$$('[data-color]').forEach(c=>{c.value=draft[c.dataset.color];c.nextElementSibling.value=draft[c.dataset.color]})};$$('[data-palette]').forEach(b=>b.addEventListener('click',()=>{const c=PALETTES[b.dataset.palette];draft={...draft,preset:b.dataset.palette,primary:c[0],secondary:c[1],tertiary:c[2]};sync()}));$$('[data-color]').forEach(c=>c.addEventListener('input',()=>{draft[c.dataset.color]=c.value;draft.preset='自定义';sync()}));$$('#theme-form input[name=primary],#theme-form input[name=secondary],#theme-form input[name=tertiary]').forEach(x=>x.addEventListener('input',()=>{if(/^#[0-9a-f]{6}$/i.test(x.value)){draft[x.name]=x.value;draft.preset='自定义';applyTheme(draft);$(`[data-color="${x.name}"]`).value=x.value}}));$('#theme-reset').addEventListener('click',()=>{const c=PALETTES['潮汐青'];draft={...draft,preset:'潮汐青',primary:c[0],secondary:c[1],tertiary:c[2]};sync()});$$('[data-close]').forEach(b=>b.addEventListener('click',()=>applyTheme(original)));$('#theme-form').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);draft.primary=f.get('primary');draft.secondary=f.get('secondary');draft.tertiary=f.get('tertiary');draft.reduceMotion=f.get('reduceMotion')==='on';try{const result=await request('/api/settings',{method:'PUT',body:{theme:draft}});state.theme=result.theme||draft;applyTheme(state.theme);closeModal();toast('主题已保存');navigate(state.route)}catch(err){toast(err.message,'error')}})}

function openAccount(){openModal(`<div class="modal-head"><div><h2>账户与安全</h2><p>${esc(state.user.displayName)} · ${esc(state.user.username)}</p></div><button class="modal-close" data-close>×</button></div><form id="password-form"><div class="field"><label>当前密码</label><input name="currentPassword" type="password" required autocomplete="current-password"></div><div class="field"><label>新密码</label><input name="newPassword" type="password" minlength="15" maxlength="128" required autocomplete="new-password"></div><button class="btn btn-soft" type="submit">修改密码</button></form><div class="danger-zone subsection"><h3>退出当前账户</h3><p class="help">如有未保存的复盘，系统会先阻止退出。</p><button class="btn btn-danger" id="logout">安全退出</button></div>`);$('#password-form').addEventListener('submit',async e=>{e.preventDefault();try{await request('/api/me/password',{method:'POST',body:Object.fromEntries(new FormData(e.currentTarget))});toast('密码已修改，请重新登录');setTimeout(init,500)}catch(err){toast(err.message,'error')}});$('#logout').addEventListener('click',async()=>{if(state.dirty){toast('请先保存或放弃当前修改','error');return}await request('/api/auth/logout',{method:'POST'});closeModal();init()})}

function openModal(content,size='',persistent=false){const root=$('#modal-root');if(!root.children.length)modalReturnFocus=document.activeElement;root.dataset.persistent=persistent?'1':'0';root.innerHTML=`<div class="modal-backdrop"><div class="modal ${size}" role="dialog" aria-modal="true">${content}</div></div>`;const modal=$('.modal',root),title=$('.modal-head h2',root);if(title){title.id='modal-title';modal.setAttribute('aria-labelledby','modal-title')}$$('.modal-close',root).forEach(button=>button.setAttribute('aria-label','关闭弹窗'));if(!persistent){$$('[data-close]',root).forEach(b=>b.addEventListener('click',()=>closeModal()));$('.modal-backdrop',root).addEventListener('mousedown',e=>{if(e.target===e.currentTarget)closeModal()})}setTimeout(()=>$('.modal input,.modal textarea,.modal button',root)?.focus(),0)}
function closeModal(force=false){const root=$('#modal-root');if(root.dataset.persistent==='1'&&!force)return;root.innerHTML='';root.dataset.persistent='0';if(modalReturnFocus?.isConnected)modalReturnFocus.focus();modalReturnFocus=null}
function attemptNavigate(next){if(!state.dirty){next();return}openModal(`<div class="modal-head"><div><h2>这页还有未保存内容</h2><p>可以继续填写，或放弃刚才的修改。</p></div></div><div class="modal-actions"><button class="btn btn-primary" data-close>继续填写</button><button class="btn btn-danger" id="discard-change">放弃修改</button></div>`);$('#discard-change').addEventListener('click',()=>{state.dirty=false;closeModal();next()})}

function bindCalendar(){
  $$('[data-calendar-shift]').forEach(button=>button.addEventListener('click',()=>{state.calendarMonth=shiftMonth(state.calendarMonth,Number(button.dataset.calendarShift));const card=$('#rail-calendar');if(card){card.innerHTML=calendarHtml();bindCalendar()}}));
  $$('[data-calendar-record]').forEach(button=>button.addEventListener('click',()=>attemptNavigate(()=>{const record=state.records.find(item=>item.id===button.dataset.calendarRecord);if(!record)return;state.route='daily';state.current=record;renderReview('daily',record.period)})));
  $$('[data-calendar]').forEach(button=>button.addEventListener('click',()=>attemptNavigate(()=>{state.route='daily';renderReview('daily',today())})));
}

function bindCommon(){
  $$('[data-nav]').forEach(b=>b.addEventListener('click',()=>attemptNavigate(()=>navigate(b.dataset.nav))));
  $$('[data-modal]').forEach(b=>b.addEventListener('click',()=>{if(b.dataset.modal==='theme')openTheme();if(b.dataset.modal==='stage')openStage();if(b.dataset.modal==='account')openAccount()}));
  $('#menu-toggle')?.addEventListener('click',e=>{const open=$('#sidebar').classList.toggle('open');$('#drawer-backdrop').classList.toggle('open',open);e.currentTarget.setAttribute('aria-expanded',String(open))});$('#drawer-backdrop')?.addEventListener('click',()=>{$('#sidebar').classList.remove('open');$('#drawer-backdrop').classList.remove('open');$('#menu-toggle')?.setAttribute('aria-expanded','false')});
  $('#rail-toggle')?.addEventListener('click',e=>{const open=$('#right-rail').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',String(open))});
  bindCalendar();
  bindActionButtons();
}
function navigate(route){state.route=route;state.navOpen=false;state.railOpen=false;if(TYPES[route])return renderReview(route,defaultPeriod(route),route==='decision');if(route==='history')return renderHistory();if(route==='actions')return renderActions();if(route==='backup')return renderBackup();if(route==='users')return renderUsers();if(route==='guide')return renderGuide();renderReview('daily')}
async function refreshStats(){state.stats=await request('/api/stats')}
async function refreshData(){const [me,rec,stats]=await Promise.all([request('/api/me'),request('/api/records'),request('/api/stats')]);state.user=me.user;state.stage=me.stage;state.theme=me.theme;state.records=rec.records;state.stats=stats;applyTheme(state.theme)}
async function boot(user){state.user=user;$('#app').innerHTML=`<div class="auth-panel"><div class="auth-card"><div class="skeleton" style="height:30px;margin-bottom:14px"></div><div class="skeleton" style="height:180px"></div></div></div>`;try{await refreshData();navigate('daily')}catch(e){if(e.status===401)return init();$('#app').innerHTML=`<div class="auth-panel"><div class="auth-card"><h1>暂时无法打开复盘室</h1><p>${esc(e.message)}</p><button class="btn btn-primary" id="retry">重试</button></div></div>`;$('#retry').addEventListener('click',()=>boot(user))}}
async function init(){try{const info=await request('/api/auth/state');if(info.user)await boot(info.user);else renderAuth(info)}catch(e){$('#app').innerHTML=`<div class="auth-panel"><div class="auth-card"><h1>服务器连接失败</h1><p>请确认服务已经启动，然后再试一次。</p><button class="btn btn-primary" id="reconnect">重新连接</button></div></div>`;$('#reconnect').addEventListener('click',()=>location.reload())}}

window.addEventListener('beforeunload',e=>{if(state.dirty){e.preventDefault();e.returnValue=''}});
document.addEventListener('keydown',e=>{const modal=$('#modal-root .modal');if(e.key==='Tab'&&modal){const focusable=$$('button:not([disabled]),input:not([disabled]),textarea:not([disabled]),select:not([disabled]),a[href],[tabindex]:not([tabindex="-1"])',modal).filter(el=>!el.closest('.hidden'));if(focusable.length){const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&(document.activeElement===first||!modal.contains(document.activeElement))){e.preventDefault();last.focus()}else if(!e.shiftKey&&(document.activeElement===last||!modal.contains(document.activeElement))){e.preventDefault();first.focus()}}}if(e.key==='Escape'&&$('#modal-root').children.length)closeModal();if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'&&state.current?.status==='draft'&&state.current.period===defaultPeriod(state.current.type)){e.preventDefault();saveCurrent()}});
init();
